// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    function setUp() public { c = new MultiplicatorX3(); }

    function testFuzz_property(uint256 value, bytes calldata data) public {
        value = bound(value, 0, 1 ether);

        Receiver rec = new Receiver();

        vm.deal(address(this), value + 1 ether);

        bool ok;
        try c.Command{value: value}(address(rec), data) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(rec.received() == value);
        } else {
            assertTrue(rec.received() == 0);
        }
    }
}

contract Receiver {
    uint256 public received;
    fallback() external payable {
        received += msg.value;
    }
    receive() external payable {
        received += msg.value;
    }
}
